lab.solution:
from dataclasses import dataclass
from enum import Enum

class Stage(Enum):
    TODO = 'todo'
    DONE = 'done'

@dataclass
class Task:
    title: str
    stage: Stage = Stage.TODO

    def __post_init__(self):
        if not isinstance(self.stage, Stage):
            raise TypeError('stage must be a Stage member')

def is_complete(task):
    return task.stage is Stage.DONE

print(is_complete(Task('Read')))
print(is_complete(Task('Ship', Stage.DONE)))
try:
    Task('Wrong type', 'done')
except TypeError:
    print('raw string rejected')
